"App: ADB Application Manager Pro ? (build ?)": "应用：ADB Application Manager Pro ?（构建 ?）",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "AppCleaner 可以通过替你点按系统设置，清除文件访问无法触及的缓存（应用“存储”界面的“清除缓存”按钮）。为此它需要本应用的无障碍服务。该服务仅在 AppCleaner 清除缓存时工作：逐个打开各应用的“应用信息”界面，点按“清除缓存”，并在屏幕熄灭或锁定时停止。屏幕上的遮罩会显示它在做什么，并可取消。不会读取任何内容，也不会向任何地方发送。在 Android 13 及更高版本中，通过文件安装的应用可能需要先“允许受限制的设置”（本应用的“应用信息”，三点菜单）。",
