"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "Aurora Store 是一款开源的 Play Store 客户端。自动检测 Play 版本是计划中的后续功能（需要匿名 Play 身份验证）；目前只会将每个应用转到其商店页面，并在已安装 Aurora Store 时用它打开。",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store：已安装 · Play Store：已安装。点按下方的应用即可打开其商店页面。",
"Aurora Store: installed · Play Store: not installed. Tap an app below to open its store page.": "Aurora Store：已安装 · Play Store：未安装。点按下方的应用即可打开其商店页面。",
"Aurora Store: not installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store：未安装 · Play Store：已安装。点按下方的应用即可打开其商店页面。",
