"Browser Use finished without an answer.": "Browser Use 结束了，但没有答案。",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "Browser Use 是开源的浏览器代理；这是它的托管云，新账户有免费额度。Ask agent 按钮会启动一个简短的浏览器任务，在网上查找该问题：可能需要一两分钟，并会消耗少量额度。它仅用于 Ask agent 按钮，不是聊天。测试密钥不收费。",
"Browser Use took too long (over 4 minutes). Try again later.": "Browser Use 用时过长（超过 4 分钟）。请稍后再试。",
"Browser Use was stopped before it had an answer.": "Browser Use 在得到答案之前被停止了。",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "浏览器自动化。需要 Node 并下载 Chromium，对手机来说可能负担较重。",
