"Choose the sign-in method in the agent's Connect sheet. The tools are installed into a Debian environment inside Termux when they have no Android build. This takes several minutes and up to about 1 GB; the providers do not support Android officially, so a tool may not run on every phone.": "在智能体的“连接”面板中选择登录方式。如果这些工具没有 Android 版本，就会安装到 Termux 内的 Debian 环境中。这需要几分钟，最多占用约 1 GB；这些提供商并未正式支持 Android，因此工具未必能在每部手机上运行。",
"Choose the version and tap its download button. The file is saved here and the browser closes by itself.": "选择版本并点按其下载按钮。文件会保存到此处，浏览器随后自动关闭。",
"Choose what the extra button on each row of the Apps list does. It is always an icon, and the ones that change with the app (Enable / Disable, Install / Uninstall, Unsuspend / Suspend) switch their icon and action to match the app's current state.": "选择“应用”列表中每一行的额外按钮的作用。它始终是一个图标，而随应用状态变化的按钮（启用 / 停用、安装 / 卸载、取消暂停 / 暂停）会切换其图标和操作，以匹配应用当前的状态。",
"Choose what to install and which starter files to write": "选择要安装的内容以及要写入的初始文件",
