"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "Claude Pro 或 Max 以及 Google 账号的登录只能在提供商自己的应用中使用：Anthropic 和 Google 不允许其他应用使用这些登录方式。因此，终端会通过在 Termux 中运行的官方命令行工具为你登录，届时会打开提供商自己的网页登录：",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "清理不再需要的内容：多余的文件、应用的可清除数据、已卸载应用的残留，以及重复存在的文件。先扫描，查看列表，取消勾选想保留的项目，然后删除。这四个工具会对普通应用无法读取的文件夹使用本应用的工作模式。",
"Clean — no engine flagged this file": "安全——没有引擎标记此文件",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "清理为模拟执行。文件会被扫描并报告，但实际上不会删除任何内容。",
