"Copilot needs a Copilot plan. GitHub retired GitHub Models in July 2026, so the Terminal uses GitHub's official Copilot CLI in Termux. Sign in there with GitHub, or save a fine-grained token with the \"Copilot Requests\" permission here and the CLI uses it.": "Copilot 需要 Copilot 订阅。GitHub 已于 2026 年 7 月停用 GitHub Models，因此终端会使用 Termux 中 GitHub 官方的 Copilot CLI。请在那里用 GitHub 登录，或在此处保存一个具有“Copilot Requests”权限的细粒度令牌，CLI 便会使用它。",
