"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "Crawl4AI 没有找到答案。请试试网页搜索或其他代理。",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "Crawl4AI 是开源的网页爬虫；这是它的托管云。新账户可获得免费额度和每月免费配额，无需银行卡。Ask agent 按钮会把问题发送给它的回答服务，该服务会搜索网页、阅读页面并写出答案。它仅用于 Ask agent 按钮，不是聊天。测试会消耗一个额度。",
