"Draw the app icons in the list with an icon pack you have installed (ADW, Nova, Apex and Go packs). Apps the pack does not cover get the pack's background and shape when it has one, and otherwise keep their own icon.": "使用你已安装的图标包（ADW、Nova、Apex 和 Go 图标包）绘制列表中的应用图标。图标包未覆盖的应用若图标包提供了背景和形状，则会套用该背景和形状，否则保留其自身图标。",
"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "DroidMind 是一个 MCP 服务器：一种让 AI 智能体通过 ADB 控制 Android 设备（应用、文件、日志、屏幕截图）的工具。它本身不提供对话功能。",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "DroidMind 已安装在 Debian 中。请使用以下命令启动：proot-distro login debian -- ~/.local/bin/droidmind --transport sse。然后将其作为 MCP 服务器添加到你的智能体（启动时会打印其地址）。",
