"EXPERT": "专家",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "每个智能体都会像其官方登录那样，将此信息保存在各自的文件中，因此两个或更多智能体可以使用同一个服务器，且任何一个都能使用它。Codex 会将远程服务器的令牌保存为环境变量，而不是保存在其文件中。我们并未在每个工具的每个版本上都进行过测试。",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "每个 Shell 都有自己的屏幕，在你使用其他标签页时也会保持打开：cd、export 和变量会从一条命令延续到下一条。“重启 Shell”会启动一个全新的 Shell。",
"Each wait is 600 seconds (10 minutes) at most.": "每次等待最长 600 秒（10 分钟）。",
