"Edited": "已编辑",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again: use Sign (this app signs with a key of its own).": "编辑 APK 会改变其内容，因此签名将不再匹配。重新签名之前，Android 不会安装它：请使用“签名”（本应用会用自己的密钥签名）。",
"Editing an APK changes its contents, so its signature no longer matches. Android will not install it until it is signed again; Sign does that with a key of this app.": "编辑 APK 会改变其内容，因此签名将不再匹配。重新签名之前，Android 不会安装它；“签名”会使用本应用的密钥完成签名。",
"Effort": "强度",
"Effort only changes anything for the agents whose own API has that knob (Claude, ChatGPT, Gemini, Grok); for the others it is kept but has no effect when chatting by API key, and none of them pass it on to their own sign-in tool in Termux.": "“强度”仅对其自身 API 提供该选项的智能体（Claude、ChatGPT、Gemini、Grok）有效；对其他智能体，该设置会被保留，但通过 API 密钥聊天时不起作用，并且它们都不会将其传递给在 Termux 中各自的登录工具。",
