"Exa found no answer for this one. Try Web search, or another agent.": "Exa 没有找到这个问题的答案。请试试网页搜索，或换一个代理。",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "Exa 是专为 AI 打造的搜索引擎。其回答服务会搜索网页，并写出注明来源的简短答案。新账户可获得免费额度。测试密钥会进行一次小型搜索（花费不到一美分）。按下“询问代理”按钮时才会把问题发送给它；在你按下之前不会发送任何内容。",
