"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "来自文件管理：通过特权后端安装，并关闭本应用的签名检查。Android 自身仍会验证签名：对于无法验证签名的 APK，会用本应用的密钥签名后安装；而由他人签名的应用，必须先卸载才能被替换（届时会先询问）。",
