"Leon is an open-source personal assistant (skills, voice) that runs on a computer with Node.js and Python. It has no Android version and is not a coding agent, so it does not chat in this Terminal.": "Leon 是一款开源个人助手（技能、语音），在装有 Node.js 和 Python 的电脑上运行。它没有 Android 版本，也不是编程智能体，因此无法在此终端中对话。",
"Leon.ai": "Leon.ai",
"Let Termux take commands from other apps": "允许 Termux 接收来自其他应用的命令",
"Let them act without asking": "允许它们无需询问直接操作",
"Lets the agent read and write files under the folder named at the end of the command (change /sdcard to taste).": "允许智能体读写命令末尾所指定文件夹下的文件（可按需修改 /sdcard）。",
"Lets the agent think in explicit steps before it acts.": "让智能体在行动前按明确的步骤进行思考。",
"Lets this app change a few protected system settings used by some advanced features.": "允许本应用更改某些高级功能所使用的少数受保护的系统设置。",
"Lets this app install the package files you choose, such as APK, APKS and XAPK files from your storage.": "允许本应用安装你选择的软件包文件，例如存储空间中的 APK、APKS 和 XAPK 文件。",
"Lets this app open another app's screen from the background, such as an app you have just installed.": "允许本应用在后台打开其他应用的界面，例如刚安装的应用。",
