"Ollama": "Ollama",
"Ollama (on-device)": "Ollama（设备端）",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "Ollama 尚未在这部手机上运行。请在下方安装，或输入运行它的电脑的地址。",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "Ollama 直接在这部手机上运行编程模型：免费，模型下载后可离线使用。它安装在 Termux 中；小型模型（1.5B 到 3B）在手机上运行最佳。电脑上的 Ollama 也可以：让它在所有地址上监听，然后在这里输入电脑的地址（如 192.168.1.20:11434/v1）。",
"On": "开启",
"On device": "在设备上",
"On this phone": "在此手机上",
"On:": "已开启：",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "每个 Shell 一次只运行一条命令；过长的输出在屏幕上以及发送给智能体的内容中都会被截断。",
"One file only": "仅一个文件",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "整个应用共用一个密钥。安装程序的扫描和 Morphe Helper 的扫描都会使用它；两者都不会再次索取，只会在缺少时指向这里。",
"One more place to find apps": "又一个查找应用的地方",
"One package per line. Duplicate entries are removed automatically.": "每行一个包名。重复项会被自动移除。",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "一种源颜色，九种将其变成完整主题的方式：浅色和深色下的强调色、背景、卡片和文字。选择一种样式，即根据下方的源颜色生成主题。",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "仅 AppCleaner 使用：它会打开系统中各应用的“应用信息”界面并点按“清除缓存”，用于文件访问无法触及的缓存。它不做其他任何事，除这些界面外绝不读取屏幕内容，并在屏幕熄灭时停止。",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "这些文件中只会写入一个带标记的块；其中原有的内容保持不变，再次运行时会刷新该块，而不是再添加一个。",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "只添加你信任的来源。补丁来源决定打过补丁的应用中会包含什么。",
"Only apps installed on this phone": "仅此手机上已安装的应用",
"Only base": "仅基础 APK",
"Only hidden files are here. Tick Show hidden files to see them.": "这里只有隐藏文件。勾选“显示隐藏文件”即可查看。",
"Only include common media files, documents and archives.": "仅包括常见的媒体文件、文档和压缩包。",
"Only list what would run for each app. Nothing is run.": "仅列出将对每个应用运行的内容，不会实际运行任何命令。",
"Only patches for apps installed on this phone": "仅此手机上已安装应用的补丁",
"Only split bundles are listed for this app. Turn on Allow split APK.": "此应用只列出拆分安装包。请开启“允许拆分 APK”。",
"Only text and compiled XML files can be compared line by line": "只有文本文件和已编译的 XML 文件才能逐行比较",
"Only the app name you typed is sent.": "只发送你输入的应用名称。",
"Only the lines written by the app you pick": "仅显示所选应用写入的日志行",
"Only the selected apps are saved.": "只保存所选应用。",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "只有本应用的文字会改变；代码框中的名称、路径和命令保持自己的字体。",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "只会向它发送这个示例问题：计算器软件包是否可以停用。",
