"The MCP button opens a sheet to give an agent extra tools (files, the web, a browser, GitHub...) through the Model Context Protocol. Pick a preset or write your own: a name, a local command or a remote address, and any key or header it needs. Pick which agents to add it to — the same server can go into two or more at once, since each agent keeps it in its own file.": "“MCP”按钮会打开一个面板，通过 Model Context Protocol 为智能体提供额外的工具（文件、网页、浏览器、GitHub 等）。选择一个预设，或自行填写：名称、本地命令或远程地址，以及所需的任何密钥或请求头。再选择要将其添加到哪些智能体——同一个服务器可以同时加入两个或更多智能体，因为每个智能体都在各自的文件中保存它。",
