"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "无障碍服务尚未就绪（未连接），因此只有它能清除的缓存会保留。之后请使用 AppCleaner 卡片上的“用无障碍清除其余部分”。",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "无障碍服务尚未就绪（已关闭），因此只有它能清除的缓存会保留。之后请使用 AppCleaner 卡片上的“用无障碍清除其余部分”。",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "无障碍服务尚未就绪（尚未同意），因此只有它能清除的缓存会保留。之后请使用 AppCleaner 卡片上的“用无障碍清除其余部分”。",
