"The request could not be sent": "无法发送请求",
"The request could not start": "无法发起请求",
"The research agent behind every Ask agent button, and the one the Application Updater asks to find an app. It reads the web and weighs what it finds to answer: what a hidden setting, a permission, a process, a log line or an app is. It is not a coding agent and it never changes anything on the phone. Perplexity is the default: it searches the web by itself and names its sources. Its key is set up in the Command-Line Interface tab.": "每个询问代理按钮背后的研究代理，也是应用更新器用来查找应用的代理。它会读取网页并权衡所得信息，来回答：某个隐藏设置、权限、进程、日志行或应用是什么。它不是编程代理，也绝不会更改手机上的任何内容。默认为 Perplexity：它会自行搜索网页并注明来源。其密钥在“命令行界面”标签页中设置。",
"The resolution the device draws at, width x height in pixels.": "设备绘制所用的分辨率，宽 x 高，单位为像素。",
"The round checkmark button (when apps are selected)": "圆形勾选按钮（选中应用时）",
"The scan failed: unknown error": "扫描失败：未知错误",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "对每个仍有文件无法触及的缓存的应用点按“清除缓存”时，屏幕会逐个短暂显示各应用的设置。遮罩会显示正在发生的事，并带有“取消”按钮。屏幕熄灭时会停止。",
