"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "然后允许本应用“Run commands in Termux environment”，并测试连接。终端设置中的“Termux 配置”会一步步引导你完成。",
"There are no saved lists to back up yet": "还没有可备份的已保存列表",
"There are no saved lists to back up yet; Restore works anyway.": "还没有可备份的已保存列表；不过仍可还原。",
"There are no saved lists to share yet": "还没有可分享的已保存列表",
"There are no usable lists in that file.": "该文件中没有可用的列表。",
"There is no key yet": "还没有密钥",
"There is no undo.": "此操作无法撤销。",
"There is nothing to delete. Scan first.": "没有可删除的内容。请先扫描。",
"These apps are currently selected for this action:": "当前为此操作选中了以下应用：",
"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "这些应用已卸载，但它们的数据文件夹仍在手机上。你勾选的应用的数据将被永久删除。",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "这些应用已卸载。没有 Root 时，应用无法看出其中哪些还留有数据，所以全部清除是安全的，但对部分应用可能什么也找不到。你勾选的应用的数据将被永久删除。",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "这些应用的发布页面位于本应用无法直接检查的网站上。可以使用 Obtainium 来跟踪它们。",
"These files are too different to compare line by line. View each one instead.": "这些文件差异过大，无法逐行比较。请分别查看每个文件。",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "关闭浏览器后它们仍会继续。“暂停”保留已下载的部分，“继续”只向网站请求剩余部分（做不到的网站会重新下载整个文件）。",
"They will be skipped unless you patch anyway, which may fail or break the app.": "除非你仍要修补，否则它们会被跳过；仍修补可能失败或损坏应用。",
"Third-party packages only": "仅第三方软件包",
"This App's ADB Key": "本应用的 ADB 密钥",
"This Shizuku version is too old. Please update Shizuku.": "此 Shizuku 版本过旧。请更新 Shizuku。",
"This action cannot be undone.": "此操作无法撤销。",
