"This app": "本应用",
"This app (sandbox)": "本应用（沙盒）",
"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "此应用无法读取存储空间。请授予“所有文件”访问权限，或手动选择字体文件（无需权限）。",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "本应用没有要求特定的触摸屏、键盘或导航方式（没有 uses-configuration 条目），因此会使用这部手机现有的硬件运行。",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "本应用没有列出所需的任何硬件或软件功能（没有 uses-feature 条目）。",
"This app has no activities.": "此应用没有 Activity。",
"This app may not run commands in Termux yet.": "本应用可能还无法在 Termux 中运行命令。",
"This app now has its own private ADB key. Tap the mode badge for details.": "本应用现在有了自己的私有 ADB 密钥。点按模式标签可查看详情。",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "无法读取此应用的代码（它没有代码，或文件不可读），所以无法判断其中是否有跟踪器。",
"This app's own authorization code. Nothing accepts it yet: it is kept here for later. It is made on this phone, stays on this phone, and you can replace it at any time.": "此应用自身的授权码。目前还没有任何对象接受它，先保存在这里备用。它在这部手机上生成，只保存在这部手机上，你可以随时更换。",
"This app's own shell - no root, ADB or package manager.": "本应用自带的 Shell——没有 root、ADB 或软件包管理器。",
"This app's own storage (private)": "此应用自己的存储空间（私有）",
"This app's own user and group id": "本应用自己的用户 ID 和组 ID",
"This app’s key · 2048-bit RSA · in secure hardware": "本应用的密钥 · 2048 位 RSA · 位于安全硬件中",
"This app’s key · 2048-bit RSA · in the Android Keystore": "本应用的密钥 · 2048 位 RSA · 位于 Android Keystore 中",
"This archive is view-only": "此压缩包仅供查看",
"This build": "此构建版本",
"This build of the app does not contain the Morphe engine, so patching is not available. Sources, the community finder and downloads still work. Install a release build of the app to patch.": "此应用构建不含 Morphe 引擎，因此无法修补。来源、社区查找和下载仍可使用。要修补，请安装应用的正式发布版本。",
"This build of the app does not contain the Morphe engine. Install a release build.": "此应用构建不含 Morphe 引擎。请安装正式发布版本。",
"This can cut the ADB connection this app uses, so you may not be able to change it back from here.": "这可能会切断本应用使用的 ADB 连接，导致无法再从这里改回。",
"This can lock you out of parts of the phone (the screen, the keyboard or accessibility).": "这可能导致手机的部分功能（屏幕、键盘或无障碍）无法使用。",
