"This only works with the agents that sign in through their own command-line tool in Termux (Claude Code, Gemini CLI, Codex, Copilot CLI, Cursor CLI, OpenCode); an agent used only with an API key cannot use one here.": "这仅适用于通过 Termux 中各自命令行工具登录的智能体（Claude Code、Gemini CLI、Codex、Copilot CLI、Cursor CLI、OpenCode）；仅使用 API 密钥的智能体无法在此使用。",
"This package carries data files that live outside the APK. Right after the install succeeds they are copied into place.": "此安装包带有存放在 APK 之外的数据文件。安装成功后，它们会立即被复制到相应位置。",
