"To search storage for APK, APKS, APKM and XAPK files, this app needs All-files access (or a working mode: ADB, Shizuku or Root).": "要在存储空间中搜索 APK、APKS、APKM 和 XAPK 文件，本应用需要“所有文件访问权限”（或工作模式：ADB、Shizuku 或 Root）。",
