"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "删除重复项时，SD Maid 会按顺序检查每条准则来决定保留哪个文件。第一个得出明确胜者的准则决定结果。拖动可重新排序，点按可更改模式。",
"When the chosen source does not have the version or does not work, This version, Newest and All versions go on with the next source, in the order above, until one delivers.": "当所选来源没有该版本或无法使用时，“此版本”“最新”和“所有版本”会按上面的顺序继续尝试下一个来源，直到有一个成功。",
