"You edited this APK, so its signature is no longer valid and Android will not install it as it is.": "你编辑过此 APK，因此其签名已失效，Android 不会按原样安装它。",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer.": "你要向一位非开发者解释一项 Android 隐藏设置（Settings.Global、Settings.Secure 或 Settings.System 数据库中的一个条目，即“settings get/put”读写的那些）。",
"You explain one Android hidden setting (an entry of the Settings.Global, Settings.Secure or Settings.System database, the ones \"settings get/put\" reads and writes) to someone who is not a developer. Say briefly: what it controls, what its values mean, what changing it does, and whether it is safe to change. Say plainly when you do not know the setting (many belong to the phone maker) instead of guessing, and then say what its name suggests. Short paragraphs, no headings.": "你要向一位非开发者解释一项 Android 隐藏设置（Settings.Global、Settings.Secure 或 Settings.System 数据库中的一个条目，即“settings get/put”读写的那些）。请简要说明：它控制什么、取值的含义、更改它会怎样，以及更改是否安全。如果不了解该设置（许多属于手机厂商），请直说，不要猜测，然后说明其名称暗示了什么。段落要短，不要标题。",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means,": "你要向一位非开发者解释一条 Android logcat 条目。请用通俗的话简要说明：这一行是什么意思，",
"You explain one Android logcat entry to someone who is not a developer. Say, in plain words and briefly: what this line means, the most likely cause, whether it matters (harmless noise, a real problem, or a crash) and, if it does matter, what to try. Use short paragraphs, no headings. If the line is too cryptic to explain with confidence, say so and say what else would help. Do not invent details.": "你要向一位非开发者解释一条 Android logcat 条目。请用通俗的话简要说明：这一行是什么意思、最可能的原因、是否重要（无害的噪声、真正的问题，还是崩溃），以及如果重要，该怎么尝试。使用短段落，不要标题。如果这一行太晦涩而无法有把握地解释，请直说，并说明还有什么能帮上忙。不要编造细节。",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.": "You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically.",
"You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside": "You help with ADB and shell command syntax in an Android terminal. Answer briefly and practically. If you want to propose exactly one command for the user to run here, put it by itself inside",
